import{z as n,x as s,o as A,c as o,q as e,j as t,D as a,d as r,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"成本预测模型","description":"","frontmatter":{"title":"成本预测模型","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-cost-forecast.md","filePath":"quant/ex-cost-forecast.md","lastUpdated":1791063341000}'),p={name:"quant/ex-cost-forecast.md"};function d(C,E,m,D,c,F){const B=s("Mermaid");return A(),o("div",null,[E[2]||(E[2]=e('<h1 id="成本预测模型" tabindex="-1">成本预测模型 <a class="header-anchor" href="#成本预测模型" aria-label="Permalink to &quot;成本预测模型&quot;">​</a></h1><div class="epigraph"><p>事前成本模型是一张条件期望表：给定单与市场的特征，预测缺口的分布；它回答参数怎么设、该不该交易，不保证市场配合。</p><footer>—— 据 Almgren, Thum, Hauptmann and Li, Direct Estimation of Equity Market Impact, Risk, 2005；Kissell and Glantz, Optimal Trading Strategies 整理</footer></div><p><a href="/quant/ex-hardware">上一课</a>给了执行栈的预算表；回到模型侧。主干 <a href="/quant/execution-cost-forecast-cap">执行成本预测</a>写了模型与组合层的接口：边际 alpha 对边际成本、保守分位进决策。本课深入模型本身的构造：特征怎么选、样本怎么定、怎么验证、怎么跟着体制更新——当一个要维护的计量产品来写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一 \\(\\eta\\) 太粗。成本在截面上随价差、波动、市值、参与率变化，在时序上随体制、费用、tick 规则变化；同一条「大单」在恐慌日与平静日是不同的成本对象。用途也决定规格：给组合层，要期望与上分位；给执行层，要条件于当日状态的成本面，选 \\(\\kappa\\) 与参与率上限；给容量研究，要外推可控。一个规格服务三个用途必然失真——先问模型为谁而建。</p><p>数据侧的坑：样本只有自己的成交（幸存于「当初愿意交易」）；已取消母单缺席；冲击与时机在实现缺口里混在一起，见 <a href="/quant/slippage-attribution">滑点归因</a> 与 <a href="/quant/tca">成交后分析 TCA</a> 的拆项。</p><h3 id="规格-从参数式到特征式" tabindex="-1">规格：从参数式到特征式 <a class="header-anchor" href="#规格-从参数式到特征式" aria-label="Permalink to &quot;规格：从参数式到特征式&quot;">​</a></h3><p>参数式基准：每股成本 \\(= s/2 + k\\,\\sigma\\,(q/\\mathrm{ADV})^{\\delta}\\) 加调整项，形状来自 <a href="/quant/sqrt-impact">线性与平方根冲击</a> 的理论，参数用横截面回归估——Almgren 等人 2005 的做法：对大量母单的已实现每股缺口，就事前特征（参与率、波动、价差、动量、日内位置）回归，\\(k\\) 与 \\(\\delta\\) 由数据说话。特征式延伸：树模型或加交互项的线性模型，捕捉「价差宽且动量逆向」的联合效应。参数式外推可解释、可进优化器；特征式拟合好但外推危险，校准域边界要记录。</p>',8)),(A(),t(l,null,{default:a(()=>[i(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E6%88%90%E6%9C%AC%E6%A8%A1%E5%9E%8B%E8%A7%84%E6%A0%BC%22%5D%20--%3E%20P%5B%22%E5%8F%82%E6%95%B0%E5%BC%8F%EF%BC%9A%E5%8D%8A%E4%BB%B7%E5%B7%AE%20%2B%20k%20%CF%83%20(q%2FADV)%5E%CE%B4%22%5D%0A%20%20B%20--%3E%20F%5B%22%E7%89%B9%E5%BE%81%E5%BC%8F%EF%BC%9A%E6%A0%91%E6%A8%A1%E5%9E%8B%E6%88%96%E5%B8%A6%E4%BA%A4%E4%BA%92%E9%A1%B9%E7%9A%84%E5%9B%9E%E5%BD%92%22%5D%0A%20%20P%20--%3E%20P1%5B%22%E5%8F%AF%E8%A7%A3%E9%87%8A%EF%BC%8C%E5%8F%AF%E8%BF%9B%E4%BC%98%E5%8C%96%E5%99%A8%EF%BC%8C%E5%A4%96%E6%8E%A8%E6%9C%89%E5%BD%A2%E7%8A%B6%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20P%20--%3E%20P2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E9%81%97%E6%BC%8F%E8%81%94%E5%90%88%E6%95%88%E5%BA%94%22%5D%0A%20%20F%20--%3E%20F1%5B%22%E6%8B%9F%E5%90%88%E5%A5%BD%EF%BC%8C%E8%83%BD%E6%8A%93%E4%BB%B7%E5%B7%AE%E5%AE%BD%E4%B8%94%E5%8A%A8%E9%87%8F%E9%80%86%E5%90%91%E8%BF%99%E7%B1%BB%E8%81%94%E5%90%88%22%5D%0A%20%20F%20--%3E%20F2%5B%22%E4%BB%A3%E4%BB%B7%EF%BC%9A%E5%A4%96%E6%8E%A8%E5%8D%B1%E9%99%A9%EF%BC%8C%E6%A0%A1%E5%87%86%E5%9F%9F%E8%A6%81%E8%AE%B0%E5%BD%95%22%5D%0A%20%20P1%20--%3E%20D%5B%22%E5%AE%9E%E5%8A%A1%E8%B7%AF%E5%BE%84%EF%BC%9A%E5%8F%82%E6%95%B0%E5%BC%8F%E5%AE%9A%E5%BD%A2%E7%8A%B6%EF%BC%8C%E7%89%B9%E5%BE%81%E5%BC%8F%E8%A1%A5%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20F1%20--%3E%20D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p><span class="marginnote">成本分布右偏且被涨跌停截断：均值受少数大缺口主导，最小二乘拟合均值会被尾部牵着走。常用做法是对数或分位回归，报告的中位数与 95 分位比均值更接近各用途的真实需要。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>样本设计：按事前特征分层抽样并保留取消母单的记录（未成交损失按对照收益定价）；制度日（指数日、涨跌停日）剔除或单独建模。估计：先用参数式定形状，再用残差对特征回归找遗漏；交互项一次只加一组，进一个、验一个。验证：按时间外推（截止前拟合、其后检验），按标的转移（小市值上学的规则去中盘股检验）；损失用分位损失而非仅 RMSE。监控：滚动重估，\\(k\\)、\\(\\delta\\) 与截距的漂移单独画图，费用与 tick 规则变更日打标签。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么形状是 \\(\\sigma\\,(q/\\mathrm{ADV})^{\\delta}\\)：提供流动性的一方承担存货与逆向选择风险，补偿随波动与所需时间放大；\\(\\delta\\approx 1/2\\) 的凹性来自冲击随参与率次线性增长的经验规律。均值拟合为什么不够：调度层的 \\(\\lambda\\) 映射方差与分位（<a href="/quant/ex-slice-scheduling-deep">子单调度的深化</a> 的增益、<a href="/quant/ex-vol-execution">波动执行的专门问题</a> 的体制触发），组合层用保守分位——消费的都是分布。</p><p><span class="marginnote">数字感受平方根律：参与率从 1% 提到 4%（四倍），因 \\(\\delta\\approx 1/2\\)，冲击只放大约 2 倍而非 4 倍；若把母单拆成 4 份分 4 天执行，每日参与率回到 1%，单日冲击减半，代价是多暴露三天。参与率、冲击与时机风险就是这样一个三角。</span></p><p>反馈回路是维护的核心机制：模型进了优化器，流量随之改变（贵名字被回避、参与率被压平），下一期校准样本不再是市场代表性样本，而是被自己策略过滤后的样本；\\(\\eta\\) 的漂移有两个来源——市场变了、自己变了。区分办法是留一部分不经模型干预的对照流量。</p><p><span class="marginnote">反馈回路可以类比餐厅点评：一家店被点评带火后，排队的人群本身就改变了菜品与体验，旧点评不再代表今天的店。成本模型进了优化器也一样——被标记为「贵」的名字被回避，下一期成交样本里它已不在，模型看到的是自己选择之后的世界。</span></p>',8)),(A(),t(l,null,{default:a(()=>[i(B,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOG%5B%22%E6%AF%8D%E5%8D%95%E6%97%A5%E5%BF%97%3A%20%E6%88%90%E4%BA%A4%20%2F%20%E5%8F%96%E6%B6%88%20%2F%20%E6%9C%AA%E5%AE%8C%E6%88%90%22%5D%20--%3E%20AUD%7B%22%E6%8B%86%E9%A1%B9%E4%B8%8E%E6%A0%B7%E6%9C%AC%E8%AE%BE%E8%AE%A1%22%7D%0A%20%20AUD%20--%3E%20FIT%5B%22%E5%8F%82%E6%95%B0%E5%BC%8F%E5%AE%9A%E5%BD%A2%E7%8A%B6%20k%2C%20delta%22%5D%0A%20%20FIT%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%E5%AF%B9%E7%89%B9%E5%BE%81%E5%9B%9E%E5%BD%92%22%5D%0A%20%20RES%20--%3E%20SPEC%5B%22%E5%8A%A0%E4%BA%A4%E4%BA%92%E9%A1%B9%2C%20%E8%BF%9B%E4%B8%80%E9%AA%8C%E4%B8%80%22%5D%0A%20%20SPEC%20--%3E%20VAL%7B%22%E6%97%B6%E9%97%B4%E5%A4%96%E6%8E%A8%20%2B%20%E6%A0%87%E7%9A%84%E8%BD%AC%E7%A7%BB%20%2B%20%E5%88%86%E4%BD%8D%E6%8D%9F%E5%A4%B1%22%7D%0A%20%20VAL%20--%3E%7C%E4%B8%8D%E8%BE%BE%E6%A0%87%7C%20FIT%0A%20%20VAL%20--%3E%7C%E8%BE%BE%E6%A0%87%7C%20PROD%5B%22%E4%B8%8A%E7%BA%BF%3A%20%E7%BB%84%E5%90%88%E5%88%86%E4%BD%8D%20%2F%20%E6%89%A7%E8%A1%8C%E6%88%90%E6%9C%AC%E9%9D%A2%22%5D%0A%20%20PROD%20--%3E%20MON%5B%22%E6%BB%9A%E5%8A%A8%E9%87%8D%E4%BC%B0%E4%B8%8E%E6%BC%82%E7%A7%BB%E6%A0%87%E7%AD%BE%22%5D%0A%20%20MON%20--%3E%20AUD%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>外推是边界的第一条：校准域内插值可信，参与率或市值超出样本后，平方根外推只是低估值而非保证，容量结论要走 <a href="/quant/capacity-participation">容量与参与率</a> 的分层 TCA。制度截断是第二条：涨跌停使分布被截断而不是延长，把不可执行当昂贵会误判。永久与临时的拆分依赖事后窗口选择，见 <a href="/quant/temp-perm-impact">瞬时冲击与永久冲击</a>，窗口规则不冻结则不可复现。分工上：模型管事前；事后归因走 <a href="/quant/tca">成交后分析 TCA</a> 的口径——两套数字必须同源校准，否则「模型说 5、实绩 12」吵不出是模型错还是执行错。</p><p><span class="marginnote">常见误区：把「模型说 5 个基点、实绩 12 个基点」直接判为模型失败。差异可能来自执行层偏离了模型假定的调度与参与率，或落在制度日。正确的检讨路径是 TCA 与模型按同源口径对账拆项，先确认两边算的是同一件事，再谈谁错。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型先问用途：组合层要分位、执行层要条件成本面、容量研究要可控外推。</li><li>参数式定形状、特征式补残差；交互项进一验一，校准域边界要记录。</li><li>成本分布右偏且被涨跌停截断：对数或分位回归，报告中位数与高分位。</li><li>验证按时间外推、按标的转移，损失用分位损失；规则变更日打标。</li><li>模型进优化器会改变流量，校准样本被自己过滤；区分市场变了与自己变了。</li><li>与 TCA 同源校准、口径互补：模型管事前，TCA 管事后。</li><li>出处：Almgren, Thum, Hauptmann and Li, <em>Risk</em>, 2005；Kissell and Glantz, <em>Optimal Trading Strategies</em>；冲击形状见主干冲击课程。</li></ul>',5))])}const _=n(p,[["render",d]]);export{u as __pageData,_ as default};
